def comps8(g, bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; c=[]
                while st:
                    x,y=st.pop(); c.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            if dx==dy==0: continue
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and g[a][b]!=bg and not seen[a][b]:
                                seen[a][b]=True; st.append((a,b))
                out.append(c)
    return out

def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    b=Counter()
    for c in comps8(g,bg):
        cols=Counter(g[x][y] for x,y in c)
        mv,cntv=c[0],cols.most_common(1)[0][0]
        rs=[x for x,y in c]; cs=[y for x,y in c]
        if len(c)==1:
            r0=rs[0]; cc=max(cs)
            if c[0][0]==r0 and c[0][1]==cc:
                # singleton at bottom-right corner of its own bbox: STAYS
                pass
            else:
                for x,y in c: b[g[x][y]][(x,y)][1]=g[x][y]
        else:
            bm=max(rs); lm=max(cs)
            stay=set()
            for x,y in c:
                if x==bm: stay.add((x,y))
                elif x==bm-1 and y==max(yy for xx,yy in c if xx==bm-1): stay.add((x,y))
            moved=[(x,y+1) for x,y in c if (x,y) not in stay]
            for x,y in moved:
                if g[x][y]==mv and 0<=y<W:
                    b[mv][(x,y)]=mv
    out=[[bg]*W for _ in range(H)]
    for k,v in b.items():
        for p,x in v.items(): out[p[0]][p[1]]=x
    return out

